package com.pilipala.marcomovie;

import android.app.*;import android.content.*;import android.os.*;import android.view.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.json.*;

/** Detail latency and lifecycle checks. Fixtures never alter user sources or history. */
public final class DetailProbe extends Instrumentation {
 MainActivity a;Bundle args;final CountDownLatch launched=new CountDownLatch(1);final JSONObject report=new JSONObject();
 @Override public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 @Override public void callActivityOnCreate(Activity activity,Bundle state){SharedPreferences p=activity.getSharedPreferences("movie",0);boolean had=p.contains("selected_site");String old=p.getString("selected_site","");p.edit().putString("selected_site","detail-probe-init").commit();try{super.callActivityOnCreate(activity,state);}finally{if(had)p.edit().putString("selected_site",old).commit();else p.edit().remove("selected_site").commit();}if(activity instanceof MainActivity){a=(MainActivity)activity;launched.countDown();}}
 boolean ui(Callable<Boolean> fn){boolean[] v={false};runOnMainSync(()->{try{v[0]=fn.call();}catch(Exception e){throw new RuntimeException(e);}});return v[0];}
 void await(Callable<Boolean> fn)throws Exception{long until=SystemClock.elapsedRealtime()+15000;while(SystemClock.elapsedRealtime()<until){if(ui(fn))return;SystemClock.sleep(10);}throw new AssertionError("wait timeout");}
 void check(String key,boolean value)throws Exception{report.put(key,value);if(!value)throw new AssertionError(key);}
 View tag(String key){return a.root.findViewWithTag(key);}
 long enter(Cms.Site site,Cms.Video video)throws Exception{long start=SystemClock.elapsedRealtime();runOnMainSync(()->a.open(new MainActivity.Screen(()->a.detail(site,video)),true));await(()->tag("detail-play")!=null);return SystemClock.elapsedRealtime()-start;}
 String response(String id)throws Exception{StringBuilder episodes=new StringBuilder();for(int i=0;i<200;i++){if(i>0)episodes.append('#');episodes.append("第 ").append(i+1).append(" 集$https://fixture.test/").append(i).append(".mp4");}return new JSONObject().put("list",new JSONArray().put(new JSONObject().put("vod_id",id).put("vod_name","选集响应样本").put("vod_play_from","样本线路").put("vod_play_url",episodes.toString()))).toString();}
 @Override public void onStart(){SharedPreferences original=null;Cms.Config old=null;CountDownLatch release=new CountDownLatch(1);try{
 Context c=getTargetContext();c.startActivity(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));if(!launched.await(15,TimeUnit.SECONDS))throw new AssertionError("launch");original=a.prefs;old=a.config;
 if("true".equals(args.getString("live"))){Cms.Site site=null;String key=a.prefs.getString("selected_site","");for(Cms.Site s:a.config.sites)if(s.key.equals(key))site=s;if(site==null)throw new AssertionError("selected source unavailable");long begin=SystemClock.elapsedRealtime();SourceEngine engine=a.engine(site);report.put("engine_ms",SystemClock.elapsedRealtime()-begin);Cms.Listing list=Cms.listing(engine.home());if(list.videos.isEmpty())list=Cms.listing(engine.homeVideos());if(list.videos.isEmpty()){java.util.List<Cms.Category> cats=Cms.categories(engine.home());if(!cats.isEmpty())list=Cms.listing(engine.category(cats.get(0).id,1));}if(list.videos.isEmpty())throw new AssertionError("no sample");Cms.Video sample=list.videos.get(0);begin=SystemClock.elapsedRealtime();String raw=engine.detail(sample.id);report.put("source_detail_ms",SystemClock.elapsedRealtime()-begin);begin=SystemClock.elapsedRealtime();Cms.Listing parsed=Cms.listing(raw);report.put("parse_ms",SystemClock.elapsedRealtime()-begin);report.put("lines",parsed.videos.isEmpty()?0:parsed.videos.get(0).lines.size());report.put("page_first_ms",enter(site,sample));report.put("page_repeat_ms",enter(site,sample));report.put("passed",true);
 }else{
 SharedPreferences fixture=c.getSharedPreferences("detail_probe_fixture",0);fixture.edit().clear().commit();Cms.Site s=new Cms.Site();s.key="detail-fixture";s.type=1;s.api="https://fixture.test/api";s.name="详情样本";Cms.Video video=new Cms.Video();video.id="sample";video.title="选集响应样本";AtomicInteger calls=new AtomicInteger();AtomicInteger cancelled=new AtomicInteger();SourceEngine source=new SourceEngine(){public String home(){return "{}";}public String category(String id,int page){return "{}";}public String search(String q,int page){return "{}";}public boolean requiresExternalRuntime(){return false;}public String detail(String id)throws Exception{calls.incrementAndGet();try{Thread.sleep(id.equals("slow")?4000:600);}catch(InterruptedException e){cancelled.incrementAndGet();throw e;}return response(id);}};
 runOnMainSync(()->{if(a.startupIntro!=null)a.startupIntro.cancel();a.prefs=fixture;a.config=new Cms.Config();a.engines.put(s.key,source);a.back.clear();});
 report.put("first_ms",enter(s,video));await(()->tag("episode:样本线路:49")!=null);report.put("repeat_ms",enter(s,video));report.put("detail_calls_after_repeat",calls.get());
 if(!"true".equals(args.getString("baseline"))){check("repeat_uses_cache",calls.get()==1);check("repeat_under_300ms",report.getLong("repeat_ms")<300);
 await(()->tag("episode:样本线路:49")!=null);runOnMainSync(()->{tag("episode:样本线路:49").requestFocus();a.open(new MainActivity.Screen(()->a.renderPage("返回测试","")),true);a.onBackPressed();});await(()->tag("episode:样本线路:49")!=null&&tag("episode:样本线路:49").hasFocus());check("return_restores_late_episode_focus",true);check("return_does_not_refetch",calls.get()==1);
 runOnMainSync(()->{tag("detail-play").requestFocus();a.scroll.scrollTo(0,0);tag("episode:样本线路:49").requestFocus();});check("secondary_uses_spring_scroll",ui(()->a.scroll instanceof TvScrollView&&((TvScrollView)a.scroll).motion!=null));SystemClock.sleep(800);
 final int[] positions=new int[2];runOnMainSync(()->{positions[0]=a.scroll.getScrollY();a.scroll.executeKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_UP));positions[1]=a.scroll.getScrollY();});check("secondary_key_has_no_position_jump",positions[0]==positions[1]);

 CountDownLatch occupied=new CountDownLatch(3);for(int i=0;i<3;i++)a.worker.execute(()->{occupied.countDown();try{release.await();}catch(InterruptedException ignored){}});if(!occupied.await(5,TimeUnit.SECONDS))throw new AssertionError("worker fixture");Cms.Video second=new Cms.Video();second.id="second";second.title="独立调度";report.put("busy_worker_detail_ms",enter(s,second));release.countDown();check("detail_not_queued_behind_general_workers",report.getLong("busy_worker_detail_ms")<2000);
 Cms.Video slow=new Cms.Video();slow.id="slow";slow.title="已离开的样本";runOnMainSync(()->a.open(new MainActivity.Screen(()->a.detail(s,slow)),true));SystemClock.sleep(150);runOnMainSync(()->a.open(new MainActivity.Screen(()->a.renderPage("已离开","")),true));SystemClock.sleep(150);check("leaving_cancels_detail",cancelled.get()>0);check("late_detail_does_not_replace_page",ui(()->tag("detail-play")==null));
 }
 report.put("passed",true);
 }
 }catch(Throwable error){try{report.put("passed",false).put("error",error.toString());}catch(Exception ignored){}}finally{release.countDown();if(a!=null){SharedPreferences p=original;Cms.Config cfg=old;runOnMainSync(()->{a.ui.removeCallbacks(a.learnPendingTitles);a.pendingTitles.clear();if(p!=null)a.prefs=p;a.config=cfg;a.engines.remove("detail-fixture");a.back.clear();a.renderPage("验证完成","");a.finish();});}}
 Bundle result=new Bundle();result.putString("result",report.toString());sendStatus(0,result);finish(Activity.RESULT_OK,new Bundle());}
}
